<?php use VazinCMS\Security;require __DIR__.'/partials/head.php';?><section class="admin-title"><div><span class="eyebrow">کتابخانه</span><h1>رسانه‌ها</h1><p>تصاویر و فایل‌های سایت را امن بارگذاری و در محتوا استفاده کنید.</p></div><span class="metric"><b><?=count($media)?></b> فایل</span></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><section class="media-layout"><form class="card upload-card" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>فایل<input type="file" name="media" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf" required></label><label>متن جایگزین<input name="alt_text" maxlength="255" placeholder="توضیح کوتاه برای دسترس‌پذیری و سئو"></label><small>حداکثر ۱۰ مگابایت؛ فایل اجرایی پذیرفته نمی‌شود.</small><button>بارگذاری امن</button></form><div class="media-grid"><?php foreach($media as $item):?><article class="media-card"><?php if(str_starts_with($item['mime_type'],'image/')):?><img src="/uploads/<?=Security::e($item['stored_name'])?>" alt="<?=Security::e($item['alt_text'])?>" loading="lazy"><?php else:?><div class="file-icon">PDF</div><?php endif;?><strong><?=Security::e($item['file_name'])?></strong><input readonly dir="ltr" value="/uploads/<?=Security::e($item['stored_name'])?>" data-copy><small><?=number_format($item['file_size']/1024,1)?> KB</small><form method="post" data-confirm="این رسانه حذف شود؟"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="danger">حذف</button></form></article><?php endforeach;?><?php if(!$media):?><div class="empty-state"><b>کتابخانه خالی است</b><p>اولین تصویر یا PDF را بارگذاری کنید.</p></div><?php endif;?></div></section><?php require __DIR__.'/partials/foot.php';?>
